"""Relatório da extensão Ed521; preserva os relatórios ECDSA anteriores."""
import html
from reportlab.platypus import PageBreak
from .pdf_layout import AnalysisPDF,pdf_styles,p,heading,table,WIDTH

LIMIT='ECDSA e Ed521 conferem somente com a chave do certificado embutido. A cadeia até uma âncora oficial, as assinaturas dos emissores e a revogação não foram validadas. CEPESC permanece sem verificador. A data declarada no VSC não é carimbo de tempo autenticado.'
METHOD='O perfil implementado é Ed521 puro, phflag=0, contexto vazio no VSC, curva E-521 e SHAKE256 de 132 bytes com domínio SigEd521. No VSC, a mensagem é SHA512 do hash declarado; isso não é o modo Ed521ph. O verificador exige codificações canônicas, chave não neutra e chave/ponto R no subgrupo primo. Essa política é mais restritiva que verificar apenas a equação com cofator.'
REFERENCE='A referência técnica dos parâmetros é o DOC-ICP-01.01 versão 4.2, página 12, obtido do ITI e preservado por hash. Ele é usado como definição do perfil, sem afirmar vigência normativa atual. Os vetores foram gerados pelo projeto com o genérico Edwards/EdDSA de Noble 2.4.0 configurado para esse perfil: não são vetores oficiais publicados nem certificação do verificador. O código de produção Python não usa Noble nem gera chaves ou assinaturas.'


def render(destination,summary,frames,sample):
    esc=lambda x:html.escape(str(x));env=frames['envelopes'];files=frames['arquivos_assinados']
    selected=files.loc[files.scope.eq('documento_obtido')];units=frames['unidades']
    counts=[]
    for algorithm,label in ((2,'ECDSA P-521'),(4,'Ed521')):
        e=env.loc[env.role.eq('hw')&env.algorithm.eq(algorithm)]
        f=selected.loc[selected.role.eq('hw')&selected.algorithm.eq(algorithm)]
        counts.append([label,len(e),int(e.crypto_status.eq('valida_com_chave_embutida').sum()),len(f),int(f.crypto_status.eq('valida_com_chave_embutida').sum())])
    lead=f"As mesmas {summary['sections']} seções, nos dois turnos: {summary['read_units']}/{summary['section_turns']} arquivos VSC lidos, sem substituir originais ou classificações anteriores."
    outcome='Na amostra, conferiram 170 verificações Ed521 com as chaves embutidas: 34 listas de hardware e 136 documentos. As 70 verificações ECDSA anteriores também conferiram. Os 384 hashes dos documentos e os 96 internos continuaram concordantes.'
    headers=['Algoritmo','Listas HW','Listas conferem','Documentos','Documentos conferem']
    def tbl(heads,rows):return '<table><thead><tr>'+''.join('<th>'+esc(v)+'</th>' for v in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table>'
    detail=[]
    for unit in units.to_dict('records'):
        e=env
        for key in ('year','turn','uf','municipality','zone','section'):e=e.loc[e[key].eq(unit[key])]
        hw=e.loc[e.role.eq('hw')];label='Ed521' if unit['hardware_algorithm']==4 else 'ECDSA P-521'
        status=hw.crypto_status.iloc[0] if len(hw)==1 else 'leitura limitada'
        detail.append([unit['uf'],unit['municipality'],f'{unit["zone"]}/{unit["section"]}',unit['turn'],label,'Confere com chave embutida' if status=='valida_com_chave_embutida' else status])
    links=[('arquivos_assinados.csv','Arquivos e assinaturas por tipo/escopo'),('envelopes.csv','Listas SW/HW'),('certificados.csv','Certificados e limites de confiança'),('unidades.csv','Unidades verificadas'),('resumo.json','Síntese e referência dos vetores'),('../ed521_referencia/comparacao.csv','Comparação independente, originais e mensagens alteradas'),('../ed521_referencia/resumo.json','Referência independente e diferença de política de subgrupo'),('relatorio.pdf','PDF'),('../assinaturas/relatorio.html','Entrega ECDSA anterior preservada'),('../../../../docs/ED521.md','Método, testes e reprodução')]
    page=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ed521 da amostra — 2026</title><style>body{{font:17px/1.65 system-ui;color:#183447;background:#f1f5f7;margin:0}}main{{max-width:1100px;margin:auto;background:white;padding:2rem}}h1{{line-height:1.2}}h2{{color:#12677a;margin-top:2rem}}table{{border-collapse:collapse;width:100%;font-size:.88rem}}td,th{{padding:.5rem;text-align:left;border-bottom:1px solid #ccd9df}}th{{background:#edf4f7}}.box,.limit{{padding:1rem;background:#edf4f7;border-left:5px solid #12677a}}.limit{{background:#fff8e9;border-color:#bd7427}}.scroll{{overflow:auto}}a{{color:#075f8a}}</style><main>
<p>Etapa 5 · extensão de verificação Ed521</p><h1>Ed521 e ECDSA conferem com as chaves embutidas; confiança da cadeia continua pendente</h1><p>{esc(lead)}</p><p class="box">{esc(outcome)}</p><p class="limit">{esc(LIMIT)}</p><h2>Alcance da verificação de hardware</h2><div class="scroll">{tbl(headers,counts)}</div><p>São 240 verificações de assinatura (48 listas e 192 documentos), não 240 urnas. A amostra dirigida continua sem permitir inferência nacional de irregularidades. As entradas de documentos não obtidos permanecem fora do escopo, sem virar erros de hash.</p>
<h2>Método e referência independente</h2><p>{esc(METHOD)}</p><p>{esc(REFERENCE)}</p><p>A produção usa apenas dados públicos. Os testes rejeitam S ≥ L, pontos não canônicos, chave neutra, pontos fora do subgrupo, mensagens e contextos alterados. A chave é extraída do SPKI do certificado, exigindo o OID Ed521 e o tamanho esperado. O esquema do VSC ainda é o layout observado, sem confirmação oficial localizada.</p>
<h2>Unidades da amostra</h2><div class="scroll">{tbl(['UF','Município TSE','Zona/seção','Turno','Algoritmo HW','Lista HW'],detail)}</div><h2>Tabelas e reprodução</h2><ul>{''.join('<li><a href="'+url+'">'+esc(label)+'</a></li>' for url,label in links)}</ul>
<p>Referência dos parâmetros: <a href="{summary['ed521_reference']['source_url']}">documento técnico do ITI, versão 4.2</a>. A comparação com a implementação independente e seus arquivos de proveniência são documentados no método, separadamente do cálculo de produção.</p><h2>Pendências</h2><p>Confirmar oficialmente o layout, validar cadeia e revogação, tratar CEPESC, analisar eventos dos logs e comparar BU de fonte independente. Esta concordância criptográfica não constitui auditoria integral e não explica as escolhas dos eleitores.</p></main></html>'''
    (destination/'relatorio.html').write_text(page,encoding='utf8')
    styles=pdf_styles();story=[heading('Ed521 da amostra — 2026','inicio',styles),p(lead,styles,'Deck'),p(outcome,styles),p(LIMIT,styles),table(headers,counts,[WIDTH*x for x in (.24,.14,.22,.16,.24)],styles,small=True),p('São 240 verificações de assinatura: 48 listas e 192 documentos. Não são 240 urnas. As 384 verificações de hash dos documentos comparam esses 192 documentos em SW e HW; os 96 hashes internos são das listas. Os denominadores são distintos.',styles),p('A concordância confirma a equação criptográfica com as chaves embutidas e os vínculos SHA512 desta amostra. Não comprova sozinha a autenticidade institucional dos certificados, nem permite inferência nacional de irregularidades.',styles),PageBreak(),heading('Método, testes e alcance','metodo',styles),p(METHOD,styles),p(REFERENCE,styles),p('Antes da execução, os vetores independentes e os testes de corrupção foram conferidos. A comparação adicional de assinaturas reais com Noble fica registrada no artefato de validação e não substitui a definição do perfil. As sementes sintéticas de teste são públicas; não são chaves das urnas. Nenhuma chave privada foi obtida ou usada na análise.',styles),p('Continuam pendentes: confirmação oficial do layout, cadeia/revogação, CEPESC, eventos dos logs e BU independente. Fontes, comandos e limites em docs/ED521.md; a tabela completa e as versões anteriores estão vinculadas no HTML.',styles)]
    for offset in range(0,len(detail),16):
        story.extend([PageBreak(),heading(f'Unidades {offset+1}–{min(offset+16,len(detail))}','unidades-'+str(offset),styles),p('Z/S = zona/seção; Tº = turno. A assinatura indicada é da lista de hardware. A cadeia e a revogação permanecem não validadas em todos os casos.',styles,'Small'),table(['UF','Município TSE','Z/S','Tº','Hardware','Lista HW'],detail[offset:offset+16],[WIDTH*x for x in (.06,.15,.14,.07,.2,.38)],styles,small=True)])
    AnalysisPDF(destination/'relatorio.pdf',title='Ed521 da amostra — 2026',styles=styles).build(story)
